Here is a complete, production-ready web application using **Node.js**, **Express**, and **SQLite** (via `better-sqlite3`).

SQLite is ideal here because its ACID transactions lock the database at the write level, guaranteeing that concurrent requests cannot exceed the 20-seat limit (no race conditions) and preventing duplicate emails atomically.

---

### 1. Project Setup

Create a new directory and initialize the project:

```bash
mkdir workshop-signup
cd workshop-signup
npm init -y
npm install express better-sqlite3
```

---

### 2. Backend: `server.js`

```javascript
const express = require('express');
const Database = require('better-sqlite3');
const path = require('path');

const app = express();
const PORT = process.env.PORT || 3000;
const MAX_SEATS = 20;

// Initialize SQLite database
const db = new Database('workshop.db');

// Ensure foreign keys and WAL mode for better concurrency
db.pragma('journal_mode = WAL');

// Create tables with constraints
db.exec(`
  CREATE TABLE IF NOT EXISTS registrations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE COLLATE NOCASE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )
`);

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// Prepared statements
const countStmt = db.prepare('SELECT COUNT(*) as count FROM registrations');
const insertStmt = db.prepare('INSERT INTO registrations (name, email) VALUES (?, ?)');

/**
 * ATOMIC REGISTRATION TRANSACTION
 * 1. Checks current seats.
 * 2. If < MAX_SEATS, attempts to insert.
 * 3. The transaction locks the DB during write, preventing race conditions.
 * 4. The UNIQUE constraint on `email` prevents duplicate sign-ups.
 */
const registerUser = db.transaction((name, email) => {
  const { count } = countStmt.get();

  if (count >= MAX_SEATS) {
    const error = new Error('SOLD_OUT');
    error.code = 'SOLD_OUT';
    throw error;
  }

  insertStmt.run(name, email);
  return { remaining: MAX_SEATS - (count + 1) };
});

// GET /api/seats - Only returns remaining seats (NO participant data exposed)
app.get('/api/seats', (req, res) => {
  try {
    const { count } = countStmt.get();
    res.json({
      total: MAX_SEATS,
      remaining: Math.max(0, MAX_SEATS - count)
    });
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch seats count' });
  }
});

// POST /api/register
app.post('/api/register', (req, res) => {
  const { name, email } = req.body;

  // Basic Validation
  if (!name || !email || typeof name !== 'string' || typeof email !== 'string') {
    return res.status(400).json({ error: 'Name and a valid email are required.' });
  }

  const cleanName = name.trim();
  const cleanEmail = email.trim().toLowerCase();

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(cleanEmail)) {
    return res.status(400).json({ error: 'Invalid email address format.' });
  }

  try {
    const result = registerUser(cleanName, cleanEmail);
    return res.status(201).json({
      message: 'Seat confirmed! See you at the workshop.',
      remaining: result.remaining
    });
  } catch (err) {
    // Catch unique constraint failure (duplicate email)
    if (err.code === 'SQLITE_CONSTRAINT_UNIQUE') {
      return res.status(409).json({ error: 'This email is already registered.' });
    }
    // Catch seat limit reached
    if (err.code === 'SOLD_OUT') {
      return res.status(410).json({ error: 'Sorry, the workshop is completely full!' });
    }
    // Internal server error
    return res.status(500).json({ error: 'An unexpected error occurred. Please try again.' });
  }
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

